CREATE OR REPLACE FUNCTION public.get_gateway_panel_metrics(p_gateway_id text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$ DECLARE u uuid:=auth.uid(); g public.gateways%rowtype; op_total bigint; wh_total bigint; tx_total bigint; mismatch_total bigint; last_test text; last_latency bigint; BEGIN IF u IS NULL THEN RAISE EXCEPTION 'unauthorized'; END IF; SELECT * INTO g FROM public.gateways WHERE id=p_gateway_id AND user_id=u; IF NOT FOUND THEN RAISE EXCEPTION 'gateway_not_found'; END IF; SELECT count(*) INTO op_total FROM public.gateway_operation_logs WHERE gateway_id=p_gateway_id; SELECT count(*) INTO wh_total FROM public.gateway_webhook_events WHERE gateway_id=p_gateway_id; SELECT count(*) INTO tx_total FROM public.gateway_transactions WHERE gateway_id=p_gateway_id; SELECT count(*) INTO mismatch_total FROM public.reconciliation_runs rr WHERE rr.gateway_id=p_gateway_id AND rr.mismatch_count>0; last_test:=CASE WHEN jsonb_typeof(coalesce(g.data,'{}'::jsonb))='object' THEN g.data->>'last_connection_test_at' ELSE NULL END; last_latency:=CASE WHEN jsonb_typeof(coalesce(g.data,'{}'::jsonb))='object' AND (g.data->>'last_connection_latency_ms')~'^[0-9]+$' THEN (g.data->>'last_connection_latency_ms')::bigint ELSE NULL END; RETURN jsonb_build_object('gateway_id',g.id,'status',g.status,'environment',g.environment,'last_connection_test_at',last_test,'last_connection_latency_ms',last_latency,'operations_total',op_total,'webhook_events_total',wh_total,'transactions_total',tx_total,'reconciliation_runs_with_mismatch',mismatch_total); END; $$; REVOKE ALL ON FUNCTION public.get_gateway_panel_metrics(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.get_gateway_panel_metrics(text) TO authenticated;